using Mon=array<int,7>;
struct ON{long id;char op;long atom=-1,x=-1,y=-1;vector<pair<long,long>>terms;};
void wr(ostream&o,const R&r){jr(o,r);}
long rterms(const R&r){return fmpq_poly_length(r.n.v)+fmpq_poly_length(r.d.v);}
struct AP{C n,d;};
ON readnode(istream&f){ON n;f>>n.id>>n.op;if(n.op=='c')f>>n.atom;else if(n.op=='m'||n.op=='a'||n.op=='s')f>>n.x>>n.y;else if(n.op=='v')f>>n.x;else if(n.op=='l'){long k;f>>k;for(long j=0;j<k;j++){long a,b;f>>a>>b;n.terms.push_back({a,b});}}else assert(n.op=='z');return n;}
R inputr(istream&f){auto p=[&](){long k;f>>k;P p;fmpq_t q;fmpq_init(q);for(long j=0;j<k;j++){long e;string s;f>>e>>s;assert(!fmpq_set_str(q,s.c_str(),10));fmpq_canonicalise(q);fmpq_poly_set_coeff_fmpq(p.v,e,q);}fmpq_clear(q);guard(p);return p;};P n=p(),d=p();return R(n,d);}
vector<long> children(const ON&n){if(n.op=='m'||n.op=='a'||n.op=='s')return{n.x,n.y};vector<long>v;if(n.op=='l')for(auto&p:n.terms)v.push_back(p.second);return v;}
R valnode(const ON&n,const map<long,R>&v,const map<long,R>&a){if(n.op=='z')return R();if(n.op=='c')return a.at(n.atom);if(n.op=='m')return mul(v.at(n.x),v.at(n.y));if(n.op=='a')return add(v.at(n.x),v.at(n.y));if(n.op=='s')return sub(v.at(n.x),v.at(n.y));assert(n.op=='l');R r;for(auto&p:n.terms)r=add(r,mul(a.at(p.first),v.at(p.second)));return r;}
